#include <iostream>
#include <algorithm>
#include <vector>
#include <deque>
#include <iterator>

int main() {
  std::vector<int> vec = {1, 2, 3, 4, 5};
  std::deque<int> deq;

  // Using back_inserter: adds to the end
  std::copy(vec.begin(), vec.end(), std::back_inserter(deq));
  for (int x : deq) std::cout << x << " "; // Output: 1 2 3 4 5
  std::cout << std::endl;
  deq.clear();

  //Using front_inserter: adds to the beginning, changing the 'front'
  std::copy(vec.begin(), vec.end(), std::front_inserter(deq));
  for (int x : deq) std::cout << x << " "; //Output: 5 4 3 2 1
  std::cout << std::endl;
  return 0;
}
